<?php require_once __DIR__ . '/includes/init.php'; redirect_if_logged_in(); $errors=[]; $next=safe_redirect_target($_GET['next']??'account.php'); if ($_SERVER['REQUEST_METHOD']==='POST') { require_csrf(); $email=strtolower(trim((string)($_POST['email']??''))); $password=(string)($_POST['password']??''); $user=$email?db_one('SELECT * FROM users WHERE email = ? AND is_active = 1',[$email]):null; if (!$user || !password_verify($password,(string)$user['password_hash'])) $errors[]='Email or password is incorrect.'; else { login_user($user,!empty($_POST['remember'])); redirect($next); } } $pageTitle='Log in'; require __DIR__.'/includes/header.php'; ?><main class="container auth-page"><div class="auth-card"><p class="eyebrow">Welcome back</p><h1>Log in to BFM</h1><?php foreach($errors as $error): ?><div class="alert alert-error"><?=e($error)?></div><?php endforeach; ?><form method="post" class="form-stack"><?=csrf_field()?><label>Email<input type="email" name="email" required autocomplete="email"></label><label>Password<input type="password" name="password" required autocomplete="current-password"></label><label class="check"><input type="checkbox" name="remember"> Remember me</label><button class="btn btn-primary btn-block">Log in</button></form><p class="auth-link">New here? <a href="<?=e(url('register.php'))?>">Create an account</a></p></div></main><?php require __DIR__.'/includes/footer.php'; ?>
